import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/tmp/conversions'
os.makedirs(UPLOAD_DIR, exist_ok=True)

# Supported output formats for document conversion
SUPPORTED_FORMATS = ['pdf', 'docx', 'odt', 'html', 'txt', 'rtf']

def sanitize_filename(name):
    """Remove path traversal but allow normal filenames"""
    return os.path.basename(name).replace('..', '')

def validate_format(fmt):
    return fmt.lower() in SUPPORTED_FORMATS

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to requested format using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    output_format = request.form.get('format', 'pdf')
    if not validate_format(output_format):
        return jsonify({'error': f'Unsupported format: {output_format}'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)

    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    # Save uploaded file
    input_path = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(input_path)

    # User can specify extra LibreOffice options for advanced conversions
    extra_opts = request.form.get('options', '')

    # Build conversion command
    cmd = f'libreoffice --headless --convert-to {output_format} {extra_opts} --outdir {UPLOAD_DIR} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        # Determine output filename
        base = os.path.splitext(filename)[0]
        output_path = os.path.join(UPLOAD_DIR, f'{base}.{output_format}')

        if os.path.exists(output_path):
            return jsonify({
                'status': 'success',
                'output': f'/downloads/{base}.{output_format}',
                'size': os.path.getsize(output_path)
            })
        else:
            return jsonify({'error': 'Output file not generated'}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Convert multiple files. Accepts JSON with file paths already on disk."""
    data = request.get_json()
    if not data or 'files' not in data:
        return jsonify({'error': 'No files specified'}), 400

    output_format = data.get('format', 'pdf')
    if not validate_format(output_format):
        return jsonify({'error': 'Unsupported format'}), 400

    results = []
    for filepath in data['files']:
        # Only allow files in upload directory
        safe_path = os.path.join(UPLOAD_DIR, os.path.basename(filepath))
        if os.path.exists(safe_path):
            cmd = f'libreoffice --headless --convert-to {output_format} --outdir {UPLOAD_DIR} {safe_path}'
            proc = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
            results.append({'file': filepath, 'success': proc.returncode == 0})
        else:
            results.append({'file': filepath, 'success': False, 'error': 'not found'})

    return jsonify({'results': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
